export const TRICK_KEY = "newt";
export const TRICKS = ["crest", "caudal", "filament", "costal", "caudate"] as const;
export const HAPPY = ["vermilion", "eftish", "palmate"] as const;
export type NewtTrickKind = (typeof TRICKS)[number];
export type NewtHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type NewtTrick = {
  kind: NewtTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type NewtHappy = {
  kind: NewtHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { vermilion: 1.58, eftish: 1.71, palmate: 1.66 } as const;
export const CAUDATE_HOLD = 17.84;
export const RELEASE_S = 1.12;
export const DUR = { caudate: CAUDATE_HOLD + RELEASE_S, crest: 2.24, caudal: 2.52, filament: 2.28, costal: 2.44 } as const;
export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: NewtTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
    if (kind === "caudate") return 74 + roll * 44;
  if (kind === "crest") return 15.8 + roll * 12.6;
  if (kind === "caudal") return 23.8 + roll * 14.8;
  if (kind === "costal") return 18.2 + roll * 13.6;
  return justFinished ? 14.0 + roll * 10.6 : 8.0 + roll * 9.4;
}

export function pickTrick(rand?: number, musicOn?: boolean, lastKind?: NewtTrickKind | string | null) {
  if (musicOn) return "caudate";
  const roll = rand == null ? Math.random() : rand;
  if (lastKind === "caudate") {
    if (roll < 0.26) return "crest";
    if (roll < 0.5) return "caudal";
    if (roll < 0.74) return "filament";
    return "costal";
  }
  if (lastKind === "crest") {
    if (roll < 0.26) return "caudate";
    if (roll < 0.5) return "caudal";
    if (roll < 0.74) return "filament";
    return "costal";
  }
  if (lastKind === "caudal") {
    if (roll < 0.22) return "caudate";
    if (roll < 0.44) return "crest";
    if (roll < 0.68) return "filament";
    return "costal";
  }
  if (roll < 0.2) return "caudate";
  if (roll < 0.4) return "crest";
  if (roll < 0.6) return "caudal";
  if (roll < 0.8) return "filament";
  return "costal";
}

export function happyCanStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function happyShouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function wantsThankYou(key: string | undefined | null) {
  return key === TRICK_KEY || key === "eft";
}

export function startThankYou(
  key: string | undefined | null,
  lastKind: NewtHappyKind | string | null | undefined,
  x: number,
  facing: 1 | -1,
  flags?: TrickFlags,
) {
  if (!wantsThankYou(key)) return null;
  if (!happyCanStart(flags || { cmd: "idle" })) return null;
  const pick = pickHappy(lastKind as NewtHappyKind | null | undefined);
  return { happy: beginHappy(pick, x, facing), kind: pick };
}

export function pickHappy(lastKind?: NewtHappyKind | null, rand?: number) {
  const pool = HAPPY.filter((k) => k !== lastKind);
  const list = pool.length ? pool : [...HAPPY];
  const roll = rand == null ? Math.random() : rand;
  return list[Math.floor(roll * list.length)] || list[0];
}

export function beginHappy(kind: NewtHappyKind | string, x: number, facing: 1 | -1): NewtHappy {
  const name = (HAPPY as readonly string[]).indexOf(kind) >= 0 ? (kind as NewtHappyKind) : "vermilion";
  return {
    kind: name,
    happy: true,
    phase: "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: name === "vermilion" ? "sit" : name === "eftish" ? "play" : "sit",
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

                    export function vermilionPose(t) {
    const u = Math.max(0, Math.min(1, t / HAPPY_DUR.vermilion));
    if (u < 0.15) {
      const s = u / 0.15;
      return { lift: s * 0.022, rot: s * 1.15, dx: 0, anim: "sit" as TrickAnim };
    }
    if (u < 0.80) {
      const flash = Math.sin(t * 5.1) + 0.18 * Math.sin(t * 10.4);
      return {
        lift: 0.022 + Math.abs(flash) * 0.014,
        rot: 1.15 + flash * 1.25,
        dx: flash * 0.0010,
        anim: "sit" as TrickAnim,
      };
    }
    const s = (u - 0.80) / 0.20;
    return { lift: 0.008 * (1 - s), rot: 0.40 * (1 - s), dx: 0, anim: "idle" as TrickAnim };
  }
  export function eftishPose(t) {
    const u = Math.max(0, Math.min(1, t / HAPPY_DUR.eftish));
    if (u < 0.13) {
      const s = u / 0.13;
      return { lift: s * 0.028, rot: s * -1.45, dx: s * 0.0014, anim: "play" as TrickAnim };
    }
    if (u < 0.84) {
      const wriggle = Math.sin(t * 7.2) + 0.24 * Math.sin(t * 12.6);
      return {
        lift: 0.028 + Math.abs(wriggle) * 0.020,
        rot: -1.45 + wriggle * 2.65,
        dx: wriggle * 0.0024,
        anim: "play" as TrickAnim,
      };
    }
    const s = (u - 0.84) / 0.16;
    return { lift: 0.010 * (1 - s), rot: -0.40 * (1 - s), dx: 0, anim: "sit" as TrickAnim };
  }
  export function palmatePose(t) {
    return {
      lift: 0.007 + Math.abs(Math.sin(t * 0.46)) * 0.016,
      rot: Math.sin(t * 0.50) * 0.88,
      dx: Math.sin(t * 0.34) * 0.0011,
      anim: "sit" as TrickAnim,
    };
  }
export function stepHappy(happy: NewtHappy, dt: number, flags: TrickFlags): NewtHappy {
  if (!happy || happy.phase === "done") return happy;
  if (happyShouldAbort(flags)) {
    return { ...happy, phase: "done", t: 0, lift: 0, rot: 0, anim: "idle", abort: true };
  }
  const next: NewtHappy = { ...happy, t: happy.t + Math.max(0, dt) };
  const hold = HAPPY_DUR[next.kind];
  if (next.kind === "vermilion") {
    const pose = vermilionPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "eftish") {
    const pose = eftishPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else {
    const pose = palmatePose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  }
  if (next.t >= hold) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  return next;
}

export function sleepHoldFrame(_key?: string | null, _frameCount?: number) {
  return null;
}

export function beginTrick(kind: NewtTrickKind, x: number, facing: 1 | -1): NewtTrick {
  const anim: TrickAnim =
    kind === "caudate"
      ? "sit"
      : kind === "crest"
        ? "play"
        : kind === "caudal"
          ? "walk"
          : kind === "filament"
            ? "sit"
            : kind === "costal"
              ? "walk"
              : "sit";
  return {
    kind: kind,
    phase: kind === "caudate" ? "hold" : "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: anim,
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}


                      export function caudatePose(t) {
    const breath = Math.sin(t * 0.16) + 0.05 * Math.sin(t * 0.41);
    const soft = Math.abs(Math.sin(t * 0.21));
    return {
      lift: 0.005 + soft * 0.010,
      rot: -0.22 + breath * 0.58,
    };
  }

  export function releasePose(t) {
    const u = Math.max(0, Math.min(1, t / RELEASE_S));
    return { lift: 0.005 * (1 - Math.sin(u * Math.PI * 0.5)), rot: -0.22 * (1 - u) };
  }

  export function crestPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.crest));
    if (u < 0.14) {
      const s = smoothstep(u / 0.14);
      return { x: fromX, lift: s * 0.055, rot: s * -0.85 * facing, anim: "play" as TrickAnim };
    }
    if (u < 0.55) {
      const s = (u - 0.14) / 0.41;
      const crest = Math.sin(s * Math.PI * 1.35);
      return {
        x: fromX + facing * crest * 0.008,
        lift: 0.055 + Math.abs(crest) * 0.028,
        rot: facing * (-0.85 + crest * 1.45),
        anim: "play" as TrickAnim,
      };
    }
    if (u < 0.82) {
      const s = (u - 0.55) / 0.27;
      const sway = Math.sin(s * Math.PI * 2.1);
      return {
        x: fromX + facing * sway * 0.005,
        lift: 0.038 + Math.abs(sway) * 0.012,
        rot: facing * (-0.35 + sway * 0.95),
        anim: "sit" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.82) / 0.18);
    return {
      x: fromX,
      lift: 0.012 * (1 - s),
      rot: facing * (-0.18 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
  export function caudalPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.caudal));
    if (u < 0.12) {
      const s = smoothstep(u / 0.12);
      return { x: fromX, lift: s * 0.016, rot: s * 1.35 * facing, anim: "walk" as TrickAnim };
    }
    if (u < 0.78) {
      const s = (u - 0.12) / 0.66;
      const wave = Math.sin(s * Math.PI * 3.6);
      const glide = Math.sin(s * Math.PI * 1.2);
      return {
        x: fromX + facing * wave * 0.034,
        lift: 0.016 + Math.abs(glide) * 0.014 + Math.abs(wave) * 0.008,
        rot: facing * (1.35 + wave * 2.85 + glide * 0.85),
        anim: "walk" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.78) / 0.22);
    return {
      x: fromX,
      lift: 0.008 * (1 - s),
      rot: facing * (0.42 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
  export function filamentPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.filament));
    if (u < 0.15) {
      const s = smoothstep(u / 0.15);
      return { x: fromX, lift: s * 0.012, rot: s * -1.05 * facing, anim: "sit" as TrickAnim };
    }
    if (u < 0.76) {
      const s = (u - 0.15) / 0.61;
      const tip = Math.sin(s * Math.PI * 4.2) + 0.22 * Math.sin(s * Math.PI * 7.1);
      return {
        x: fromX + facing * tip * 0.007,
        lift: 0.012 + Math.abs(tip) * 0.010,
        rot: facing * (-1.05 + tip * 1.85),
        anim: "sit" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.76) / 0.24);
    return {
      x: fromX,
      lift: 0.006 * (1 - s),
      rot: facing * (-0.28 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
  export function costalPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.costal));
    if (u < 0.12) {
      const s = smoothstep(u / 0.12);
      return { x: fromX, lift: s * 0.018, rot: s * 0.95 * facing, anim: "walk" as TrickAnim };
    }
    if (u < 0.80) {
      const s = (u - 0.12) / 0.68;
      const groove = Math.sin(s * Math.PI * 2.8);
      const crawl = Math.sin(s * Math.PI * 1.35);
      return {
        x: fromX + facing * crawl * 0.026,
        lift: 0.018 + Math.abs(groove) * 0.014 + Math.abs(crawl) * 0.010,
        rot: facing * (0.95 + groove * 2.15 + crawl * 1.25),
        anim: "walk" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.80) / 0.20);
    return {
      x: fromX,
      lift: 0.008 * (1 - s),
      rot: facing * (0.28 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
export function stepTrick(trick: NewtTrick, dt: number, flags: TrickFlags): NewtTrick {
  if (!trick || trick.phase === "done") return trick;
  if (shouldAbort(flags) && trick.kind !== "crest" && trick.kind !== "caudal" && trick.kind !== "filament" && trick.kind !== "costal") {
    return { ...trick, phase: "done", t: 0, lift: 0, rot: 0, anim: "idle", abort: true };
  }
  const next: NewtTrick = { ...trick, t: trick.t + Math.max(0, dt) };
  if (next.kind === "caudate") {
    if (next.t < CAUDATE_HOLD) {
      const pose = caudatePose(next.t);
      next.phase = "hold";
      next.lift = pose.lift;
      next.rot = pose.rot;
      next.anim = "sit";
      return next;
    }
    if (next.t < CAUDATE_HOLD + RELEASE_S) {
      const pose = releasePose(next.t - CAUDATE_HOLD);
      next.phase = "release";
      next.lift = pose.lift;
      next.rot = pose.rot;
      next.anim = "sit";
      return next;
    }
    return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  }
  const hold = DUR[next.kind];
  const u = next.t / hold;
  if (next.kind === "crest") {
    const pose = crestPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "caudal") {
    const pose = caudalPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "filament") {
    const pose = filamentPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else {
    const pose = costalPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  }
  if (u >= 1) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  return next;
}
